1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
4	  rune: 25,
5	  moonstone: 25,
6	};
7	const MAIN_ITEM_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	};
13	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
14	  ...MAIN_ITEM_BASE_PREMIUM_BY_TYPE,
15	  ...COMPONENT_BASE_PREMIUM_BY_TYPE,
16	};
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	const CURSED_SURCHARGE_RATE = 0.5;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
22	const LOYALTY_DISCOUNT_RATE = 0.2;
23	
24	type Item = {
25	  type: string;
26	  material?: string;
27	  enchantment?: number;
28	  cursed?: boolean;
29	};
30	
31	type Step = {
32	  op: string;
33	  items: Item[];
34	};
35	
36	type Scenario = {
37	  customer: { yearsWithMHPCO: number };
38	  steps: Step[];
39	};
40	
41	type QuoteResult = {
42	  premium: number;
43	};
44	
45	type ScenarioOutput = {
46	  results: QuoteResult[];
47	};
48	
49	const isComponent = (item: Item): boolean =>
50	  item.type in COMPONENT_BASE_PREMIUM_BY_TYPE;
51	
52	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
53	  sameTypeItems.length === COMPONENT_BLOCK_SIZE &&
54	  sameTypeItems.every(isComponent);
55	
56	const groupByType = (items: Item[]): Item[][] => {
57	  const groups = new Map<string, Item[]>();
58	  for (const item of items) {
59	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
60	  }
61	  return [...groups.values()];
62	};
63	
64	const basePremiumForItem = (item: Item): number =>
65	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
66	
67	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
68	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
69	  return sameTypeItems.reduce(
70	    (total, item) => total + basePremiumForItem(item),
71	    0,
72	  );
73	};
74	
75	const basePremiumForItems = (items: Item[]): number =>
76	  groupByType(items).reduce(
77	    (total, group) => total + basePremiumForGroup(group),
78	    0,
79	  );
80	
81	const cursedSurcharge = (item: Item): number =>
82	  item.cursed ? basePremiumForItem(item) * CURSED_SURCHARGE_RATE : 0;
83	
84	const hasHighEnchantment = (item: Item): boolean =>
85	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
86	
87	const highEnchantmentSurcharge = (item: Item): number =>
88	  hasHighEnchantment(item)
89	    ? basePremiumForItem(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
90	    : 0;
91	
92	const totalItemSurcharges = (items: Item[]): number =>
93	  items.reduce(
94	    (total, item) =>
95	      total + cursedSurcharge(item) + highEnchantmentSurcharge(item),
96	    0,
97	  );
98	
99	const loyaltyDiscount = (basePremium: number, yearsWithMHPCO: number): number =>
100	  yearsWithMHPCO > 0 ? basePremium * LOYALTY_DISCOUNT_RATE : 0;
101	
102	const premiumBeforeProcessingFee = (
103	  items: Item[],
104	  yearsWithMHPCO: number,
105	): number => {
106	  const basePremium = basePremiumForItems(items);
107	  return (
108	    basePremium +
109	    totalItemSurcharges(items) +
110	    basePremium * FIRST_INSURANCE_SURCHARGE_RATE -
111	    loyaltyDiscount(basePremium, yearsWithMHPCO)
112	  );
113	};
114	
115	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
116	  results: scenario.steps.map((step) => ({
117	    premium: Math.ceil(
118	      premiumBeforeProcessingFee(step.items, scenario.customer.yearsWithMHPCO) +
119	        PROCESSING_FEE,
120	    ),
121	  })),
122	});
